BEGIN IMMEDIATE;
CREATE TABLE delivery_leases(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,session_key TEXT NOT NULL,lifetime TEXT NOT NULL,owner_id TEXT NOT NULL,epoch INTEGER NOT NULL CHECK(epoch>0),expires_at_ms INTEGER NOT NULL,PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,session_key,lifetime));
CREATE TABLE event_outbox(cursor INTEGER PRIMARY KEY AUTOINCREMENT,event_id TEXT NOT NULL UNIQUE,organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,session_key TEXT NOT NULL,lifetime TEXT NOT NULL,run_id TEXT NOT NULL,event_seq INTEGER NOT NULL,payload_json TEXT NOT NULL,payload_digest TEXT NOT NULL,delivered INTEGER NOT NULL DEFAULT 0 CHECK(delivered IN(0,1)),claim_owner TEXT,claim_epoch INTEGER,UNIQUE(organization_id,tenant_id,project_id,agent_uid,run_id,event_seq),UNIQUE(organization_id,tenant_id,project_id,agent_uid,event_id,payload_digest),FOREIGN KEY(run_id,event_seq) REFERENCES events(run_id,seq));
CREATE INDEX outbox_pending ON event_outbox(organization_id,tenant_id,project_id,agent_uid,delivered,cursor);
CREATE TABLE publication_inbox(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,consumer TEXT NOT NULL,event_id TEXT NOT NULL,payload_digest TEXT NOT NULL,PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,consumer,event_id),FOREIGN KEY(organization_id,tenant_id,project_id,agent_uid,event_id,payload_digest) REFERENCES event_outbox(organization_id,tenant_id,project_id,agent_uid,event_id,payload_digest));
CREATE TRIGGER outbox_immutable BEFORE UPDATE OF event_id,organization_id,tenant_id,project_id,agent_uid,session_key,lifetime,run_id,event_seq,payload_json,payload_digest ON event_outbox BEGIN SELECT RAISE(ABORT,'immutable outbox payload'); END;
INSERT INTO schema_migrations VALUES(22,CAST(strftime('%s','now') AS INTEGER)*1000);
COMMIT;
